import {api} from '../api.js';
import {focusCrmLead, showCrmLeadFocus} from '../crm-lead-link.js';
import {loadWorkflow, bindWorkflow, profileModal, applyResearchState, researchMessage, researchDetails} from './piq_workflow_ui.js';
import {startResearch, restoreResearch} from './piq_research_ui.js';
import {bindDiscovery, isLiveProspect, providerLabel, potentialLabel, liveDetails, evidenceLabel, matchDetails, fitLabel} from './piq_discovery_ui.js';
import {state, isGlobalAdmin, selectedTenant} from '../state.js';
import {$, $$, badge, dateFmt, empty, esc, loading, modal, money, number, pageHead, pct, readonlyBanner, setActiveNav, statusTone, toast} from '../ui.js';
import {clientAdminCorrectionApplies, renderClientAdminCorrection, enhanceWebsiteForClientAdmin} from './client_admin_correction.js';
import {v53ClientExperienceApplies, renderV53ClientExperience} from './v53_client_experience.js';

const title = value => String(value || '').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const kpi = (label,value,detail='') => `<section class="kpi-card"><span>${label}</span><strong>${value}</strong><small>${detail}</small></section>`;
const field = (label,name,type='text',value='',required=false,placeholder='') => `<div class="field"><label>${esc(label)}</label><input name="${esc(name)}" type="${type}" value="${esc(value ?? '')}" ${required?'required':''} placeholder="${esc(placeholder)}"></div>`;
const textarea = (label,name,value='',placeholder='') => `<div class="field full"><label>${esc(label)}</label><textarea name="${esc(name)}" placeholder="${esc(placeholder)}">${esc(value ?? '')}</textarea></div>`;
const select = (label,name,options,value='') => `<div class="field"><label>${esc(label)}</label><select name="${esc(name)}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const fmtDateTime = value => value ? new Date(value).toLocaleString() : '—';
const parseLines = value => String(value||'').split(/\n|,/).map(x=>x.trim()).filter(Boolean);
const canWrite = readOnly => !readOnly;

export async function renderUnifiedPage(route, ctx, readOnly=false) {
  setActiveNav(route);
  const page = $('#page'); page.innerHTML = loading();
  if (!state.selectedTenantId) { page.innerHTML = empty('Select a client','Choose a client from the portfolio.'); return; }
  try {
    if (v53ClientExperienceApplies(route)) { await renderV53ClientExperience(route,page,ctx); return; }
    if (clientAdminCorrectionApplies(route)) { await renderClientAdminCorrection(route,page,ctx); return; }
    if (route === 'home') return await dashboard(page,ctx,readOnly);
    if (route === 'website') return await website(page,ctx,readOnly);
    if (route === 'crm') return await crm(page,ctx,readOnly);
    if (route === 'piq') return await piq(page,ctx,readOnly);
    if (route === 'campaigns') return await campaigns(page,ctx,readOnly);
    if (route === 'email') return await emailActivities(page,ctx,readOnly);
    if (route === 'reports') return await reports(page,ctx,readOnly);
    // Preserve the accepted operational renderer for modules that are not
    // implemented by this unified page. This prevents a route from remaining
    // on the initial Loading state in RMR Owner client-workspace previews.
    if (['forecast','training','organization','solutions'].includes(route)) {
      return await ctx.renderClientOperational(route, readOnly);
    }
    throw new Error(`Unsupported client workspace route: ${route}`);
  } catch (error) {
    console.error('Unified workspace rendering failed', error);
    page.innerHTML = empty('Unable to load this workspace',error.message);
    toast(error.message,'error');
  }
}

async function dashboard(page,ctx,readOnly) {
  const data = await api(`/api/tenants/${state.selectedTenantId}/workspace`);
  const t=data.tenant,c=data.counts,enabled=data.modules.filter(x=>x.enabled);
  const manageNote=isGlobalAdmin()?`<div class="workspace-role-note"><strong>${state.managedSession?'Managed service session active':'Client workspace preview'}</strong><span>${state.managedSession?'Actions are performed as you and written to the audit history.':'Start an authorized session from the banner to perform client work.'}</span></div>`:'';
  page.innerHTML=`${pageHead(`${esc(t.name)} Workspace`,'Run the website, opportunities, prospecting, campaigns, communication and reporting from one client operating system.',`<button class="button secondary" id="open-public-site">Open Website</button><button class="button" data-route="crm">Add Opportunity</button>`)}${manageNote}
  <section class="unified-hero"><div><div class="eyebrow">RMR GLOBAL CLIENT OPERATIONS</div><h2>One place to attract, manage and convert opportunity.</h2><p>Website activity, ProspectIQ, CRM, campaigns, email and reporting stay connected to the same client tenant.</p><div class="hero-actions"><button class="button" data-route="website">Manage Website</button><button class="button secondary" data-route="piq">Find Prospects</button><button class="button secondary" data-route="campaigns">Create Content</button></div></div><div class="growth-score"><span>Open pipeline</span><strong>${money(c.pipeline_cents)}</strong><small>${number(c.open_opportunities)} active opportunities</small></div></section>
  <div class="kpi-grid">${kpi('Website leads',number(c.appointments),'Appointment requests')}${kpi('CRM leads',number(c.leads),'New and qualified')}${kpi('ProspectIQ',number(c.piq_records),'Scored prospects')}${kpi('Campaigns',number(c.campaigns),'Content initiatives')}${kpi('Social drafts',number(c.social_drafts),'Human-reviewed posts')}${kpi('Emails',number(c.emails),'Recorded outreach')}${kpi('Won opportunities',number(c.won_opportunities),'Closed revenue activity')}${kpi('SEO actions',number(c.seo_open),'Open improvements')}</div>
  <div class="grid two"><section class="card"><div class="card-head"><div><h2>Your growth tools</h2><p class="muted">Only activated modules appear here.</p></div></div><div class="module-launch-grid">${enabled.filter(x=>!['home','solutions'].includes(x.key)).map(m=>`<button class="module-launch" data-route="${esc(m.key)}"><span class="module-icon">${m.icon}</span><span><strong>${esc(m.label)}</strong><small>${moduleDescription(m.key)}</small></span><b>→</b></button>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2>Recent activity</h2><p class="muted">CRM, website, outreach and audit history.</p></div><button class="text-button" data-route="email">Full timeline</button></div><div class="timeline-list">${data.recent_activity.length?data.recent_activity.map(event=>timelineRow(event)).join(''):empty('No recent activity','Work completed in this tenant will appear here.')}</div></section></div>`;
  $$('[data-route]').forEach(btn=>btn.addEventListener('click',()=>ctx.navigate(btn.dataset.route)));
  $('#open-public-site')?.addEventListener('click',()=>window.open(data.website?.mode==='managed'?`/sites/${data.website.slug}`:(data.website?.external_url||`/sites/${data.website?.slug||''}?preview=1`),'_blank','noopener'));
}

function moduleDescription(key){return ({website:'Build, edit, publish and measure',crm:'Leads, contacts, opportunities and tasks',piq:'Target, discover, research and qualify',campaigns:'Campaigns, social content and approval',email:'Outreach and complete activity history',forecast:'Sales forecast by account and month',reports:'Cross-channel growth and revenue evidence',training:'Role-based product guidance',organization:'Users, roles and business settings'})[key]||'Open module';}
function timelineRow(e){return `<div class="timeline-row"><span class="timeline-dot"></span><div class="grow"><strong>${esc(e.title)}</strong><small>${esc(e.source)} · ${esc(e.actor||'System')} · ${fmtDateTime(e.created_at)}</small>${e.detail?`<p>${esc(e.detail).slice(0,220)}</p>`:''}</div></div>`;}

async function website(page,ctx,readOnly){
  const [siteData,content]=await Promise.all([api(`/api/tenants/${state.selectedTenantId}/website`),api(`/api/tenants/${state.selectedTenantId}/website-content`)]);
  const tab=state.unifiedTab.website||'studio';
  const tabs=[['studio','Website Studio'],['media','Media'],['blog','Blog'],['resources','Resources'],['team','Team Profiles'],['seo','SEO'],['appointments','Appointments']];
  const actions=canWrite(readOnly)?websiteActions(tab):'';
  page.innerHTML=`${pageHead('Website & Content','Build an RMR-managed website or connect an existing site, then manage content, SEO and lead capture.',`<a class="button secondary" href="${esc(siteData.preview_url)}" target="_blank">Preview</a><a class="button" href="${esc(siteData.public_url)}" target="_blank">Open Published Site</a>`)}${readOnly?readonlyBanner():''}
  <div class="module-summary"><div><span>Website mode</span><strong>${title(siteData.site.mode)}</strong></div><div><span>Status</span><strong>${title(siteData.site.status)}</strong></div><div><span>Pages</span><strong>${siteData.pages.length}</strong></div><div><span>Content assets</span><strong>${content.media.length+content.posts.length+content.resources.length}</strong></div></div>
  <div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${tab===k?'active':''}" data-website-tab="${k}">${l}</button>`).join('')}</div><div class="module-toolbar">${actions}</div><div id="website-module">${renderWebsiteTab(tab,siteData,content,readOnly)}</div>`;
  $$('[data-website-tab]').forEach(btn=>btn.addEventListener('click',()=>{state.unifiedTab.website=btn.dataset.websiteTab;ctx.navigate('website')}));
  bindWebsiteTab(tab,siteData,content,ctx,readOnly);
  await enhanceWebsiteForClientAdmin(page);
}
function websiteActions(tab){return ({media:'<button class="button" id="add-media">+ Add Media</button><button class="button secondary" id="upload-media">Upload File</button>',blog:'<button class="button" id="add-blog">+ New Blog Post</button>',resources:'<button class="button" id="add-resource">+ New Resource</button>',team:'<button class="button" id="add-team">+ New Profile</button>',seo:'<button class="button" id="add-seo">+ SEO Action</button>',appointments:'',studio:''})[tab]||'';}
function renderWebsiteTab(tab,data,content,readOnly){
  if(tab==='studio')return renderStudio(data,readOnly);
  if(tab==='media')return `<div class="asset-grid">${content.media.length?content.media.map(x=>`<article class="asset-card">${x.media_type==='image'?`<img src="${esc(x.url)}" alt="${esc(x.alt_text)}">`:`<div class="asset-placeholder">${x.media_type==='video'?'▶':'DOC'}</div>`}<div><strong>${esc(x.title)}</strong><small>${esc(x.alt_text||x.media_type)}</small><div class="chip-row">${(x.tags_json||[]).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div>${!readOnly?`<button class="text-button danger-text" data-delete-media="${x.id}">Delete</button>`:''}</div></article>`).join(''):empty('No media yet','Add image, video, logo or document assets.')}</div>`;
  if(tab==='blog')return `<div class="content-list">${content.posts.length?content.posts.map(x=>`<article class="content-row"><div class="grow"><div class="eyebrow">${esc(x.status)}</div><h3>${esc(x.title)}</h3><p>${esc(x.summary)}</p><small>${x.published_at?`Published ${dateFmt(x.published_at)}`:'Draft'} · /${esc(x.slug)}</small></div>${!readOnly?`<button class="button secondary small" data-edit-blog="${x.id}">Edit</button><button class="text-button danger-text" data-delete-blog="${x.id}">Delete</button>`:''}</article>`).join(''):empty('No blog posts','Create the first search-friendly article.')}</div>`;
  if(tab==='resources')return `<div class="grid two">${content.resources.length?content.resources.map(x=>`<article class="card"><div class="eyebrow">${esc(x.resource_type)}</div><h3>${esc(x.title)}</h3><p class="muted">${esc(x.description)}</p><p class="tiny">${x.lead_capture_required?'Lead capture required':'Direct access'} · ${esc(x.status)}</p><a class="button secondary small" href="${esc(x.url)}" target="_blank">Open</a>${!readOnly?`<button class="text-button danger-text" data-delete-resource="${x.id}">Delete</button>`:''}</article>`).join(''):empty('No resources','Add buyer guides, checklists or downloadable content.')}</div>`;
  if(tab==='team')return `<div class="grid three">${content.team.length?content.team.map(x=>`<article class="card team-profile"><div class="profile-avatar">${esc(x.full_name).split(/\s+/).map(y=>y[0]).join('').slice(0,2)}</div><h3>${esc(x.full_name)}</h3><strong>${esc(x.title)}</strong><p class="muted">${esc(x.bio)}</p><small>${esc(x.email)} ${x.phone?`· ${esc(x.phone)}`:''}</small>${!readOnly?`<button class="text-button danger-text" data-delete-team="${x.id}">Delete</button>`:''}</article>`).join(''):empty('No team profiles','Add customer-facing professional profiles.')}</div>`;
  if(tab==='seo')return `<div class="grid">${content.seo.length?content.seo.map(x=>`<article class="list-item"><span class="grow"><strong>${esc(x.title)}</strong><small>${esc(x.recommendation)} · ${esc(x.item_type)}</small></span>${badge(title(x.priority),statusTone(x.priority))}${badge(title(x.status),statusTone(x.status))}${!readOnly?`<button class="button secondary small" data-seo-status="${x.id}" data-current="${x.status}">${x.status==='complete'?'Reopen':'Mark Complete'}</button>`:''}</article>`).join(''):empty('No SEO actions','Create the first content, technical or local SEO action.')}</div>`;
  return `<section class="table-card"><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Person</th><th>Contact</th><th>Preferred time</th><th>Message</th><th>Status</th><th>Received</th><th></th></tr></thead><tbody>${content.appointments.length?content.appointments.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.email)}<br>${esc(x.phone)}</td><td>${esc(x.preferred_time)}</td><td>${esc(x.message)}</td><td>${badge(title(x.status),statusTone(x.status))}</td><td>${fmtDateTime(x.created_at)}</td><td>${!readOnly?`<button class="button secondary small" data-appointment="${x.id}">Update</button>`:''}</td></tr>`).join(''):'<tr><td colspan="7">No appointment requests yet.</td></tr>'}</tbody></table></div></section>`;
}
function renderStudio(data,readOnly){const site=data.site;return `<div class="website-overview"><section class="card"><h2>Website configuration</h2><div class="form-grid">${select('Website mode','mode',[['managed','RMR Managed Website'],['custom','Custom Connected Website'],['external','Existing External Website']],site.mode)}${field('Company name','company_name','text',site.company_name)}${field('Wordmark','wordmark','text',site.wordmark)}${field('External website URL','external_url','url',site.external_url)}${field('Primary color','primary_color','color',site.primary_color)}${field('Accent color','accent_color','color',site.accent_color)}${select('Status','status',[['draft','Draft'],['published','Published']],site.status)}</div>${!readOnly?'<button class="button" id="save-site">Save Website Settings</button>':''}</section><section class="card"><h2>Pages</h2><div class="grid">${data.pages.map(p=>`<button class="page-summary" data-page-id="${p.id}"><span><strong>${esc(p.title)}</strong><small>/${esc(p.slug)} · ${esc(p.status)}</small></span><b>→</b></button>`).join('')}</div>${!readOnly?'<button class="button secondary" id="add-page-unified">+ Add Page</button>':''}</section></div><section class="card"><h2>Live preview</h2><iframe class="unified-site-frame" src="${esc(data.preview_url)}"></iframe></section>`;}
function bindWebsiteTab(tab,data,content,ctx,readOnly){
  if(tab==='studio'){$('#save-site')?.addEventListener('click',async()=>{try{const root=$('#website-module');await api(`/api/tenants/${state.selectedTenantId}/website`,{method:'PATCH',body:{mode:$('[name=mode]',root).value,company_name:$('[name=company_name]',root).value,wordmark:$('[name=wordmark]',root).value,external_url:$('[name=external_url]',root).value,primary_color:$('[name=primary_color]',root).value,accent_color:$('[name=accent_color]',root).value,status:$('[name=status]',root).value}});toast('Website settings saved');ctx.navigate('website')}catch(e){toast(e.message,'error')}});$('#add-page-unified')?.addEventListener('click',()=>addPage(ctx));$$('[data-page-id]').forEach(btn=>btn.addEventListener('click',()=>editPage(btn.dataset.pageId,data,ctx,readOnly)))}
  $('#add-media')?.addEventListener('click',()=>mediaModal(ctx));$('#upload-media')?.addEventListener('click',()=>uploadMediaModal(ctx));$$('[data-delete-media]').forEach(btn=>btn.addEventListener('click',()=>remove(`/api/website-media/${btn.dataset.deleteMedia}`,'Media deleted',ctx,'website')));
  $('#add-blog')?.addEventListener('click',()=>blogModal(null,ctx));$$('[data-edit-blog]').forEach(btn=>btn.addEventListener('click',()=>blogModal(content.posts.find(x=>x.id===btn.dataset.editBlog),ctx)));$$('[data-delete-blog]').forEach(btn=>btn.addEventListener('click',()=>remove(`/api/blog-posts/${btn.dataset.deleteBlog}`,'Blog post deleted',ctx,'website')));
  $('#add-resource')?.addEventListener('click',()=>resourceModal(ctx));$$('[data-delete-resource]').forEach(btn=>btn.addEventListener('click',()=>remove(`/api/website-resources/${btn.dataset.deleteResource}`,'Resource deleted',ctx,'website')));
  $('#add-team')?.addEventListener('click',()=>teamModal(ctx));$$('[data-delete-team]').forEach(btn=>btn.addEventListener('click',()=>remove(`/api/website-team/${btn.dataset.deleteTeam}`,'Profile deleted',ctx,'website')));
  $('#add-seo')?.addEventListener('click',()=>seoModal(data.pages,ctx));$$('[data-seo-status]').forEach(btn=>btn.addEventListener('click',async()=>{const item=content.seo.find(x=>x.id===btn.dataset.seoStatus);try{await api(`/api/seo-items/${item.id}`,{method:'PATCH',body:{page_id:item.page_id,item_type:item.item_type,title:item.title,status:item.status==='complete'?'open':'complete',priority:item.priority,recommendation:item.recommendation,evidence:item.evidence_json||{}}});toast('SEO action updated');ctx.navigate('website')}catch(e){toast(e.message,'error')}}));
  $$('[data-appointment]').forEach(btn=>btn.addEventListener('click',()=>appointmentModal(content.appointments.find(x=>x.id===btn.dataset.appointment),ctx)));
}
function mediaModal(ctx){modal({title:'Add media by URL',body:`<form class="form-grid">${field('Title','title','text','',true)}${select('Media type','media_type',[['image','Image'],['video','Video'],['document','Document'],['logo','Logo']])}${field('URL','url','url','',true)}${field('Alternative text','alt_text','text','')}${field('Tags (comma separated)','tags','text','')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-media">Add Media</button>',onOpen:(root,close)=>$('#save-media',root).addEventListener('click',async()=>{const f=$('form',root);if(!f.reportValidity())return;try{await api(`/api/tenants/${state.selectedTenantId}/website-media`,{method:'POST',body:{title:f.title.value,media_type:f.media_type.value,url:f.url.value,alt_text:f.alt_text.value,tags:f.tags.value.split(',').map(x=>x.trim()).filter(Boolean)}});toast('Media added');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function uploadMediaModal(ctx){modal({title:'Upload media file',body:`<form id="upload-form" class="form-grid">${field('Title','title','text','',true)}${field('Alternative text','alt_text','text','')}${field('Tags (comma separated)','tags','text','')}<div class="field full"><label>File</label><input name="file" type="file" required accept="image/*,video/*,.pdf"></div></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="upload-file">Upload</button>',onOpen:(root,close)=>$('#upload-file',root).addEventListener('click',async()=>{const f=$('#upload-form',root);if(!f.reportValidity())return;const body=new FormData();body.append('title',f.title.value);body.append('alt_text',f.alt_text.value);body.append('tags',f.tags.value);body.append('file',f.file.files[0]);try{await api(`/api/tenants/${state.selectedTenantId}/website-media/upload`,{method:'POST',body});toast('File uploaded');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function blogModal(post,ctx){modal({title:post?'Edit blog post':'New blog post',wide:true,body:`<form class="form-grid">${field('Title','title','text',post?.title||'',true)}${field('URL slug','slug','text',post?.slug||'')}${select('Status','status',[['draft','Draft'],['published','Published']],post?.status||'draft')}${field('Featured image URL','featured_image_url','url',post?.featured_image_url||'')}${textarea('Summary','summary',post?.summary||'')}${textarea('Article body','body',post?.body||'')}${field('SEO title','seo_title','text',post?.seo_title||'')}${textarea('SEO description','seo_description',post?.seo_description||'')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-blog">Save Post</button>',onOpen:(root,close)=>$('#save-blog',root).addEventListener('click',async()=>{const f=$('form',root);if(!f.reportValidity())return;const body=Object.fromEntries(new FormData(f).entries());try{await api(post?`/api/blog-posts/${post.id}`:`/api/tenants/${state.selectedTenantId}/blog-posts`,{method:post?'PATCH':'POST',body});toast('Blog post saved');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function resourceModal(ctx){modal({title:'New downloadable resource',body:`<form class="form-grid">${field('Title','title','text','',true)}${select('Type','resource_type',[['guide','Guide'],['checklist','Checklist'],['video','Video'],['worksheet','Worksheet']])}${field('URL','url','url','',true)}${select('Status','status',[['draft','Draft'],['published','Published']],'published')}${textarea('Description','description','')}<label class="list-item full"><input name="lead_capture_required" type="checkbox" checked> Require contact information before access</label></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-resource">Save Resource</button>',onOpen:(root,close)=>$('#save-resource',root).addEventListener('click',async()=>{const f=$('form',root);try{await api(`/api/tenants/${state.selectedTenantId}/website-resources`,{method:'POST',body:{title:f.title.value,description:f.description.value,resource_type:f.resource_type.value,url:f.url.value,lead_capture_required:f.lead_capture_required.checked,status:f.status.value}});toast('Resource saved');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function teamModal(ctx){modal({title:'New public team profile',body:`<form class="form-grid">${field('Full name','full_name','text','',true)}${field('Professional title','title','text','')}${field('Email','email','email','')}${field('Phone','phone','text','')}${field('Photo URL','photo_url','url','')}${field('Display order','display_order','number','0')}${textarea('Biography','bio','')}<label class="list-item full"><input name="visible" type="checkbox" checked> Visible on website</label></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-team">Save Profile</button>',onOpen:(root,close)=>$('#save-team',root).addEventListener('click',async()=>{const f=$('form',root);try{await api(`/api/tenants/${state.selectedTenantId}/website-team`,{method:'POST',body:{full_name:f.full_name.value,title:f.title.value,bio:f.bio.value,email:f.email.value,phone:f.phone.value,photo_url:f.photo_url.value,display_order:Number(f.display_order.value),visible:f.visible.checked}});toast('Team profile saved');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function seoModal(pages,ctx){modal({title:'New SEO action',body:`<form class="form-grid">${select('Page','page_id',[['','Site-wide'],...pages.map(x=>[x.id,x.title])])}${select('Type','item_type',[['content','Content'],['local_seo','Local SEO'],['technical','Technical'],['metadata','Metadata']])}${field('Action title','title','text','',true)}${select('Priority','priority',[['low','Low'],['medium','Medium'],['high','High']],'medium')}${textarea('Recommendation','recommendation','')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-seo">Create Action</button>',onOpen:(root,close)=>$('#save-seo',root).addEventListener('click',async()=>{const f=$('form',root);try{await api(`/api/tenants/${state.selectedTenantId}/seo-items`,{method:'POST',body:{page_id:f.page_id.value||null,item_type:f.item_type.value,title:f.title.value,status:'open',priority:f.priority.value,recommendation:f.recommendation.value,evidence:{}}});toast('SEO action created');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function appointmentModal(item,ctx){modal({title:'Update appointment request',body:`<p><strong>${esc(item.name)}</strong><br>${esc(item.email)} · ${esc(item.phone)}</p><p>${esc(item.message)}</p>${select('Status','status',[['new','New'],['contacted','Contacted'],['scheduled','Scheduled'],['complete','Complete'],['closed','Closed']],item.status)}`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-appointment">Save</button>',onOpen:(root,close)=>$('#save-appointment',root).addEventListener('click',async()=>{try{await api(`/api/appointments/${item.id}`,{method:'PATCH',body:{status:$('[name=status]',root).value}});toast('Appointment updated');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function addPage(ctx){modal({title:'Add website page',body:`<form class="form-grid">${field('Page title','title','text','',true)}${field('URL slug','slug','text','',true)}${select('Status','status',[['draft','Draft'],['published','Published']],'published')}${field('SEO title','seo_title','text','')}${textarea('SEO description','seo_description','')}<label class="list-item full"><input name="show_in_nav" type="checkbox" checked> Show in navigation</label></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-page">Create Page</button>',onOpen:(root,close)=>$('#save-page',root).addEventListener('click',async()=>{const f=$('form',root);try{await api(`/api/tenants/${state.selectedTenantId}/website/pages`,{method:'POST',body:{title:f.title.value,slug:f.slug.value,status:f.status.value,show_in_nav:f.show_in_nav.checked,seo_title:f.seo_title.value,seo_description:f.seo_description.value}});toast('Page created');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}
function editPage(pageId,data,ctx,readOnly){const p=data.pages.find(x=>x.id===pageId);const sections=data.sections.filter(x=>x.page_id===pageId);modal({title:`${esc(p.title)} Page`,wide:true,body:`<div class="form-grid">${field('Page title','title','text',p.title)}${field('URL slug','slug','text',p.slug)}${select('Status','status',[['draft','Draft'],['published','Published']],p.status)}${field('SEO title','seo_title','text',p.seo_title||'')}${textarea('SEO description','seo_description',p.seo_description||'')}</div><h3>Page sections</h3><div class="grid">${sections.map(x=>`<div class="list-item"><span class="grow"><strong>${title(x.section_type)}</strong><small>Position ${x.position} · ${x.visible?'Visible':'Hidden'}</small></span></div>`).join('')}</div>`,footer:`<button class="button secondary" data-close-modal>Close</button>${!readOnly?'<button class="button" id="save-page-edit">Save Page</button>':''}`,onOpen:(root,close)=>$('#save-page-edit',root)?.addEventListener('click',async()=>{try{await api(`/api/website/pages/${p.id}`,{method:'PATCH',body:{title:$('[name=title]',root).value,slug:$('[name=slug]',root).value,status:$('[name=status]',root).value,seo_title:$('[name=seo_title]',root).value,seo_description:$('[name=seo_description]',root).value}});toast('Page saved');close();ctx.navigate('website')}catch(e){toast(e.message,'error')}})});}

async function crm(page,ctx,readOnly){
  const [summary,accounts,leads,opps,contacts,activities]=await Promise.all([api(`/api/tenants/${state.selectedTenantId}/crm/summary`),api(`/api/tenants/${state.selectedTenantId}/accounts`),api(`/api/tenants/${state.selectedTenantId}/leads`),api(`/api/tenants/${state.selectedTenantId}/opportunities`),api(`/api/tenants/${state.selectedTenantId}/contacts`),api(`/api/tenants/${state.selectedTenantId}/activities`)]);
  const focus=focusCrmLead(leads.leads);if(focus)leads.leads=focus.rows;
  const tab=state.unifiedTab.crm||'opportunities';const all={accounts:accounts.accounts,leads:leads.leads,opportunities:opps.opportunities,contacts:contacts.contacts,activities:activities.activities};
  page.innerHTML=`${pageHead('CRM & Sales Pipeline','Capture every relationship, lead, opportunity and activity—then connect them to PIQ, email and reporting.',!readOnly?'<button class="button secondary" id="crm-import">Import</button><button class="button" id="crm-new">+ New</button>':'')}${readOnly?readonlyBanner():''}<div class="kpi-grid">${kpi('Accounts',number(summary.accounts),'Customer and partner relationships')}${kpi('Leads',number(summary.leads),'New prospects')}${kpi('Open opportunities',number(summary.opportunities),'Active pipeline')}${kpi('Weighted pipeline',money(summary.weighted_pipeline_cents),'Probability-adjusted')}</div><section class="card"><div class="crm-search"><input id="crm-search" placeholder="Search accounts, contacts, leads or opportunities"><button class="button secondary" id="run-crm-search">Search</button><button class="button secondary" id="crm-duplicates">Find duplicates</button></div><div id="crm-search-results"></div></section><div class="tabs">${['accounts','leads','opportunities','contacts','activities'].map(x=>`<button class="tab ${tab===x?'active':''}" data-crm-tab="${x}">${title(x)}</button>`).join('')}</div>${renderCrmTable(tab,all,readOnly)}`;
  showCrmLeadFocus(page,focus);
  $$('[data-crm-tab]').forEach(btn=>btn.addEventListener('click',()=>{state.unifiedTab.crm=btn.dataset.crmTab;ctx.navigate('crm')}));
  $('#crm-new')?.addEventListener('click',()=>crmNewModal(tab,all,ctx));$('#crm-import')?.addEventListener('click',()=>crmImportModal(ctx));$('#run-crm-search').addEventListener('click',()=>runCrmSearch());$('#crm-search').addEventListener('keydown',e=>{if(e.key==='Enter')runCrmSearch()});$('#crm-duplicates').addEventListener('click',()=>duplicatesModal(ctx));
  $$('[data-convert-lead]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api(`/api/leads/${btn.dataset.convertLead}/convert`,{method:'POST',body:{}});toast('Lead converted to account and opportunity');ctx.navigate('crm')}catch(e){toast(e.message,'error')}}));
  $$('[data-email-record]').forEach(btn=>btn.addEventListener('click',()=>emailModal({opportunity_id:btn.dataset.emailRecord,recipient_email:'',recipient_name:''},ctx)));
}
function renderCrmTable(tab,data,readOnly){
  if(tab==='accounts')return `<section class="table-card"><table class="data-table"><thead><tr><th>Account</th><th>Owner</th><th>Status</th><th>Value</th><th>Risk</th><th>Source</th></tr></thead><tbody>${data.accounts.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.owner_name||'Unassigned')}</td><td>${badge(x.status,statusTone(x.status))}</td><td>${money(x.annual_value_cents)}</td><td>${badge(x.risk,statusTone(x.risk))}</td><td>${esc(x.source)}</td></tr>`).join('')}</tbody></table></section>`;
  if(tab==='leads')return `<section class="table-card"><table class="data-table"><thead><tr><th>Company</th><th>Contact</th><th>Email</th><th>Source</th><th>Status</th><th></th></tr></thead><tbody>${data.leads.map(x=>`<tr><td><strong>${esc(x.company_name||'Individual')}</strong></td><td>${esc(x.contact_name)}</td><td>${esc(x.email)}</td><td>${esc(x.source)}</td><td>${badge(x.status,statusTone(x.status))}</td><td>${!readOnly&&x.status!=='Converted'?`<button class="button secondary small" data-convert-lead="${x.id}">Convert</button>`:''}</td></tr>`).join('')}</tbody></table></section>`;
  if(tab==='opportunities')return `<section class="pipeline-board">${['Prospecting','Qualified','Proposal','Verbal Commitment','Closed Won'].map(stage=>`<div class="pipeline-column"><div class="pipeline-head"><strong>${stage}</strong><span>${data.opportunities.filter(x=>x.stage===stage).length}</span></div>${data.opportunities.filter(x=>x.stage===stage).map(x=>`<article class="opportunity-card"><div class="eyebrow">${esc(x.source)}</div><h3>${esc(x.name)}</h3><strong>${money(x.value_cents)}</strong><p>${esc(x.next_action||'No next action')}</p><small>${pct(x.probability_pct)} · ${dateFmt(x.expected_close_date)}</small>${!readOnly?`<button class="text-button" data-email-record="${x.id}">Send email / record activity</button>`:''}</article>`).join('')||'<div class="pipeline-empty">No opportunities</div>'}</div>`).join('')}</section>`;
  if(tab==='contacts')return `<section class="table-card"><table class="data-table"><thead><tr><th>Contact</th><th>Account</th><th>Title</th><th>Email</th><th>Phone</th></tr></thead><tbody>${data.contacts.map(x=>`<tr><td><strong>${esc(`${x.first_name} ${x.last_name}`)}</strong></td><td>${esc(x.account_name||'')}</td><td>${esc(x.title)}</td><td>${esc(x.email)}</td><td>${esc(x.phone)}</td></tr>`).join('')}</tbody></table></section>`;
  return `<section class="timeline-list card">${data.activities.length?data.activities.map(x=>timelineRow({title:x.subject||x.activity_type,source:'CRM',actor:x.user_name||'Client user',created_at:x.created_at,detail:x.body})).join(''):empty('No activities','Emails, calls, notes and tasks appear here.')}</section>`;
}
async function runCrmSearch(){const q=$('#crm-search').value.trim();if(!q)return;try{const d=await api(`/api/tenants/${state.selectedTenantId}/crm/search?q=${encodeURIComponent(q)}`);const rows=[...d.accounts.map(x=>['Account',x.name]),...d.contacts.map(x=>['Contact',`${x.first_name} ${x.last_name}`]),...d.leads.map(x=>['Lead',x.company_name||x.contact_name]),...d.opportunities.map(x=>['Opportunity',x.name])];$('#crm-search-results').innerHTML=rows.length?`<div class="search-results">${rows.map(([type,name])=>`<div class="list-item"><span class="badge gray">${type}</span><strong class="grow">${esc(name)}</strong></div>`).join('')}</div>`:empty('No matches','Try another name, email or company.')}catch(e){toast(e.message,'error')}}
function crmNewModal(tab,data,ctx){const defaultType=tab==='opportunities'?'opportunity':tab==='accounts'?'account':tab==='contacts'?'contact':'lead';modal({title:'Create CRM record',body:`${select('Record type','type',[['lead','Lead'],['account','Account'],['opportunity','Opportunity'],['contact','Contact'],['activity','Activity']],defaultType)}<form id="crm-record-form" class="form-grid"></form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-crm-record">Create Record</button>',onOpen:(root,close)=>{const form=$('#crm-record-form',root);const render=()=>{const type=$('[name=type]',root).value;form.innerHTML=type==='lead'?`${field('Company','company_name','text','')}${field('Contact name','contact_name','text','')}${field('Email','email','email','')}${field('Phone','phone','text','')}${field('Source','source','text','Manual')}${textarea('Notes','notes','')}`:type==='account'?`${field('Account name','name','text','',true)}${field('Annual value','annual_value','number','0')}${field('Source','source','text','Manual')}${textarea('Notes','notes','')}`:type==='opportunity'?`${field('Opportunity name','name','text','',true)}${select('Account','account_id',[['','No account yet'],...data.accounts.map(x=>[x.id,x.name])])}${field('Value','value','number','0')}${select('Stage','stage',[['Prospecting','Prospecting'],['Qualified','Qualified'],['Proposal','Proposal'],['Verbal Commitment','Verbal Commitment'],['Closed Won','Closed Won']])}${field('Probability %','probability','number','25')}${field('Expected close','expected_close_date','date','')}${field('Source','source','text','Manual')}${textarea('Next action','next_action','')}`:type==='contact'?`${select('Account','account_id',[['','No account'],...data.accounts.map(x=>[x.id,x.name])])}${field('First name','first_name','text','')}${field('Last name','last_name','text','')}${field('Title','title','text','')}${field('Email','email','email','')}${field('Phone','phone','text','')}`:`${select('Account','account_id',[['','No account'],...data.accounts.map(x=>[x.id,x.name])])}${select('Type','activity_type',[['Note','Note'],['Call','Call'],['Task','Task'],['Meeting','Meeting']])}${field('Subject','subject','text','')}${textarea('Details','body','')}`};render();$('[name=type]',root).addEventListener('change',render);$('#save-crm-record',root).addEventListener('click',async()=>{const type=$('[name=type]',root).value;try{let path,body;if(type==='lead'){path=`/api/tenants/${state.selectedTenantId}/leads`;body={company_name:form.company_name.value,contact_name:form.contact_name.value,email:form.email.value,phone:form.phone.value,source:form.source.value,status:'New',notes:form.notes.value}}else if(type==='account'){path=`/api/tenants/${state.selectedTenantId}/accounts`;body={name:form.name.value,status:'Active',annual_value_cents:Math.round(Number(form.annual_value.value||0)*100),source:form.source.value,risk:'Low',notes:form.notes.value}}else if(type==='opportunity'){path=`/api/tenants/${state.selectedTenantId}/opportunities`;body={account_id:form.account_id.value||null,name:form.name.value,stage:form.stage.value,value_cents:Math.round(Number(form.value.value||0)*100),probability_pct:Number(form.probability.value||0),expected_close_date:form.expected_close_date.value||null,source:form.source.value,next_action:form.next_action.value}}else if(type==='contact'){path=`/api/tenants/${state.selectedTenantId}/contacts`;body={account_id:form.account_id.value||null,first_name:form.first_name.value,last_name:form.last_name.value,title:form.title.value,email:form.email.value,phone:form.phone.value,primary_contact:false}}else{path=`/api/tenants/${state.selectedTenantId}/activities`;body={account_id:form.account_id.value||null,activity_type:form.activity_type.value,subject:form.subject.value,body:form.body.value}}await api(path,{method:'POST',body});toast(`${title(type)} created`);close();ctx.navigate('crm')}catch(e){toast(e.message,'error')}})}});}
function crmImportModal(ctx){modal({title:'Import leads or accounts',wide:true,body:`<p>Paste rows copied from a spreadsheet. Use one row per record:</p><p class="tiny"><strong>Company | Contact | Email | Phone | Source</strong></p><div class="field"><textarea id="crm-import-rows" style="min-height:240px" placeholder="Sample Company\tJordan Smith\tjordan@example.com\t602-555-0101\tReferral"></textarea></div><div id="crm-import-preview"></div>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button secondary" id="preview-crm-import">Preview</button><button class="button" id="commit-crm-import" disabled>Import Ready Rows</button>',onOpen:(root,close)=>{let rows=[];$('#preview-crm-import',root).addEventListener('click',async()=>{rows=$('#crm-import-rows',root).value.split('\n').filter(Boolean).map(line=>{const [company_name,contact_name,email,phone,source]=line.split(/\t|,/);return {company_name:company_name?.trim(),contact_name:contact_name?.trim(),email:email?.trim(),phone:phone?.trim(),source:source?.trim()||'Imported List'}});try{const d=await api(`/api/tenants/${state.selectedTenantId}/crm/import-preview`,{method:'POST',body:{filename:'pasted-list.csv',rows}});rows=d.preview;$('#crm-import-preview',root).innerHTML=`<div class="notice-card"><strong>${d.ready} ready · ${d.duplicates} duplicates · ${d.errors} errors</strong></div>`;$('#commit-crm-import',root).disabled=!d.ready}catch(e){toast(e.message,'error')}});$('#commit-crm-import',root).addEventListener('click',async()=>{try{const d=await api(`/api/tenants/${state.selectedTenantId}/crm/import`,{method:'POST',body:{filename:'pasted-list.csv',rows}});toast(`${d.created} CRM records imported`);close();ctx.navigate('crm')}catch(e){toast(e.message,'error')}})}});}
async function duplicatesModal(ctx){try{const d=await api(`/api/tenants/${state.selectedTenantId}/crm/duplicates`);modal({title:'Potential duplicate accounts',wide:true,body:d.groups.length?d.groups.map(g=>`<div class="card"><h3>${esc(g.normalized_name)}</h3>${g.accounts.map(x=>`<div class="list-item"><span class="grow"><strong>${esc(x.name)}</strong><small>${esc(x.source)} · ${money(x.annual_value_cents)}</small></span></div>`).join('')}</div>`).join(''):empty('No duplicates found','Account names are currently unique.'),footer:'<button class="button" data-close-modal>Done</button>'})}catch(e){toast(e.message,'error')}}

async function piq(page,ctx,readOnly){
  const tenantId=state.selectedTenantId;
  const workflow=await loadWorkflow(tenantId); const data=workflow.data,target={profile:workflow.profile}; readOnly=readOnly||!workflow.collection.can_write;
  if(state.selectedTenantId!==tenantId || state.route!=='piq')return;
  page.innerHTML=`${pageHead('ProspectIQ','Define who you want to reach, discover or import prospects, review evidence and assess fit before moving records into CRM.',!readOnly?'<button class="button secondary" id="piq-import">Import List</button><button class="button" id="run-discovery">Pull Leads</button>':'')}${readOnly?readonlyBanner():''}<div class="grid two"><section class="card"><div class="card-head"><div><h2>Target profile</h2><p class="muted">The criteria ProspectIQ uses to find and score opportunities.</p></div>${!readOnly?'<button class="button secondary small" id="edit-target">Edit</button>':''}</div>${target.profile?`<h3>${esc(target.profile.name)}</h3><p><strong>Industries:</strong> ${esc((target.profile.industries_json||[]).join(', '))}</p><p><strong>Markets:</strong> ${esc((target.profile.locations_json||[]).join(', '))}</p><div class="chip-row">${(target.profile.keywords_json||[]).map(x=>`<span class="chip">${esc(x)}</span>`).join('')}</div>`:empty('No target profile','Create a target profile before discovery.')}</section><section class="card"><h2>ProspectIQ results</h2><div class="kpi-grid compact">${kpi('Records',number(data.opportunities.length),'Scored prospects')}${kpi('Enhanced',number(data.opportunities.filter(x=>x.enhanced).length),'Research completed')}${kpi('In CRM',number(data.opportunities.filter(x=>x.moved_to_crm).length),'Preserved attribution')}</div></section></div><section class="table-card"><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Company</th><th>Score</th><th>Signal</th><th>Evidence</th><th>Potential</th><th>Status</th><th>Actions</th></tr></thead><tbody>${data.opportunities.map(x=>`<tr><td><strong>${esc(x.company_name)}</strong><br><small>${esc(providerLabel(x))}</small></td><td><span class="score-ring">${x.score}</span></td><td>${esc(x.signal)}</td><td>${x.evidence_count}</td><td>${potentialLabel(x)}</td><td>${badge(fitLabel(x),statusTone(x.status))}</td><td><button class="button secondary small" data-piq-profile="${x.id}">View Details</button>${false?`<button class="button small" data-piq-enhance="${x.id}">Enhance</button>`:''}${!readOnly&&!x.moved_to_crm?`<button class="button secondary small" data-piq-crm="${x.id}">Move to CRM</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;
  $('#edit-target')?.addEventListener('click',()=>targetModal(target.profile,ctx));const controls=bindWorkflow(page,workflow,ctx,$('#run-discovery'),readOnly); applyResearchState(page,data.opportunities); if(controls.enabled) bindDiscovery({page,button:$('#run-discovery'),...controls,tenantId,refresh:()=>ctx.navigate('piq'),demoMessage:result=>`${result.created.length} prospects discovered`});$('#piq-import')?.addEventListener('click',()=>piqImportModal(ctx));$$('[data-piq-profile]').forEach(btn=>btn.addEventListener('click',()=>piqProfileModal(btn.dataset.piqProfile,ctx,readOnly)));$$('[data-piq-enhance]').forEach(btn=>btn.addEventListener('click',()=>enhancePiq(btn.dataset.piqEnhance,ctx)));$$('[data-piq-crm]').forEach(btn=>btn.addEventListener('click',async()=>{if(btn.disabled)return;btn.disabled=true;try{await api(`/api/piq/${btn.dataset.piqCrm}/move-to-crm`,{method:'POST',body:{}});toast('Prospect moved to CRM');ctx.navigate('piq')}catch(e){btn.disabled=false;toast(e.message,'error')}}));
  restoreResearch(ctx,data.opportunities);
}
function targetModal(profile,ctx){return profileModal(profile,ctx);}
function piqImportModal(ctx){modal({title:'Import prospect list',wide:true,body:`<p>Paste: <strong>Company | Signal | Score | Estimated value</strong></p><div class="field"><textarea id="piq-rows" style="min-height:240px" placeholder="Example Company\tExpanding into Arizona\t78\t50000"></textarea></div><div id="piq-preview"></div>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button secondary" id="preview-piq">Preview</button><button class="button" id="commit-piq" disabled>Import</button>',onOpen:(root,close)=>{let batch=null;$('#preview-piq',root).addEventListener('click',async()=>{const rows=$('#piq-rows',root).value.split('\n').filter(Boolean).map(line=>{const [company_name,signal,score,value]=line.split(/\t|,/);return {company_name:company_name?.trim(),signal:signal?.trim(),score:Number(score||60),estimated_value_cents:Math.round(Number(value||0)*100)}});try{const d=await api(`/api/tenants/${state.selectedTenantId}/piq/import-preview`,{method:'POST',body:{filename:'pasted-prospects.csv',rows}});batch=d.batch;$('#piq-preview',root).innerHTML=`<div class="notice-card"><strong>${d.preview.filter(x=>x.status==='ready').length} ready · ${d.batch.duplicate_count} duplicates · ${d.batch.error_count} errors</strong></div>`;$('#commit-piq',root).disabled=!d.preview.some(x=>x.status==='ready')}catch(e){toast(e.message,'error')}});$('#commit-piq',root).addEventListener('click',async()=>{try{const d=await api(`/api/tenants/${state.selectedTenantId}/piq/import`,{method:'POST',body:{filename:'pasted-prospects.csv',rows:[],batch_id:batch.id}});toast(`${d.count} prospects imported`);close();ctx.navigate('piq')}catch(e){toast(e.message,'error')}})}});}
async function piqProfileModal(id,ctx,readOnly){try{const d=await api(`/api/piq/${id}/profile`);modal({title:d.opportunity.company_name,wide:true,body:`<div class="kpi-grid compact">${kpi('Match score',d.opportunity.score,'Profile fit')}${kpi('Evidence',d.evidence.length,'Source-linked facts')}${kpi('Potential',potentialLabel(d.opportunity),'Estimated value')}</div>${liveDetails(d.opportunity)}${matchDetails(d.match)}${researchDetails(d.research?.latest,d.opportunity)}<p>CRM: ${d.opportunity.moved_to_crm?'In CRM':'Not yet moved'}</p><p>${esc([d.research?.latest?researchMessage(d.research.latest):'',d.research?.reason||''].filter(Boolean).join(' '))}</p><div class="notice-card"><strong>Opportunity signal</strong><p>${esc(d.opportunity.signal)}</p></div><h3>Evidence and research</h3><div class="grid">${d.evidence.map(e=>`<div class="list-item"><span class="grow"><strong>${esc(e.fact)}</strong><small>${esc(e.source_name)} · Confidence ${e.confidence_pct}% ${['google_places','openai_research'].includes(e.provider)?evidenceLabel(e):e.verified?'· Verified':''}</small></span>${badge(e.evidence_type.replaceAll('_',' '),(e.provider==='google_places'?e.evidence_state==='confirmed':e.verified)?'green':'amber')}</div>`).join('')}</div>`,footer:`<button class="button secondary" data-close-modal>Close</button>${!readOnly&&d.research?.eligible!==false?'<button class="button" id="adaptive-research">Run Adaptive Research</button>':''}`,onOpen:(root,close)=>$('#adaptive-research',root)?.addEventListener('click',async()=>{try{await startResearch(id,ctx,close)}catch(e){toast(e.message,'error')}})})}catch(e){toast(e.message,'error')}}
function enhancePiq(id,ctx){modal({title:'Confirm paid profile enhancement',body:'<p>The configured per-record enhancement charge will be recorded before the profile is enhanced.</p><label class="list-item"><input id="confirm-piq-charge" type="checkbox"> I authorize this enhancement.</label>',footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="confirm-enhance">Enhance</button>',onOpen:(root,close)=>$('#confirm-enhance',root).addEventListener('click',async()=>{if(!$('#confirm-piq-charge',root).checked){toast('Confirmation is required','error');return}try{await api(`/api/piq/${id}/enhance`,{method:'POST',body:{payment_confirmation:true}});toast('Profile enhanced');close();ctx.navigate('piq')}catch(e){toast(e.message,'error')}})});}

async function campaigns(page,ctx,readOnly){
  const data=await api(`/api/tenants/${state.selectedTenantId}/marketing`);const tab=state.unifiedTab.campaigns||'campaigns';
  page.innerHTML=`${pageHead('Campaigns & Social','Plan campaigns, create human-reviewed content, generate outreach and record manual publishing from the client workspace.',!readOnly?'<button class="button" id="create-campaign">+ New Campaign</button>':'')}${readOnly?readonlyBanner():''}<div class="tabs">${[['campaigns','Campaigns'],['social','Social Content'],['email','Email Outreach'],['calendar','Content Calendar']].map(([k,l])=>`<button class="tab ${tab===k?'active':''}" data-marketing-tab="${k}">${l}</button>`).join('')}</div><div class="module-toolbar">${!readOnly&&tab==='social'?'<button class="button" id="generate-social">Generate Social Posts</button>':''}${!readOnly&&tab==='email'?'<button class="button" id="generate-outreach">Generate Outreach</button>':''}</div>${renderMarketingTab(tab,data,readOnly)}`;
  $$('[data-marketing-tab]').forEach(btn=>btn.addEventListener('click',()=>{state.unifiedTab.campaigns=btn.dataset.marketingTab;ctx.navigate('campaigns')}));$('#create-campaign')?.addEventListener('click',()=>campaignModal(ctx));$('#generate-social')?.addEventListener('click',()=>socialModal(ctx));$('#generate-outreach')?.addEventListener('click',()=>generateOutreachModal(ctx));$$('[data-publish-social]').forEach(btn=>btn.addEventListener('click',()=>publishSocialModal(btn.dataset.publishSocial,ctx)));$$('[data-copy-text]').forEach(btn=>btn.addEventListener('click',async()=>{const item=data.social.find(x=>x.id===btn.dataset.copyText);try{await navigator.clipboard.writeText(item.post_text);toast('Post copied')}catch{toast('Copy unavailable','error')}}));$$('[data-copy-tags]').forEach(btn=>btn.addEventListener('click',async()=>{const item=data.social.find(x=>x.id===btn.dataset.copyTags);try{await navigator.clipboard.writeText(item.hashtags||'');toast('Hashtags copied')}catch{toast('Copy unavailable','error')}}));
}
function renderMarketingTab(tab,data,readOnly){
  if(tab==='campaigns')return `<div class="grid three">${data.campaigns.map(x=>`<article class="card"><div class="eyebrow">${esc(x.channel)}</div><h3>${esc(x.title)}</h3><p class="muted">${esc(x.content)}</p>${badge(x.status,statusTone(x.status))}<small>${x.scheduled_at?`Scheduled ${fmtDateTime(x.scheduled_at)}`:'No scheduled date'}</small></article>`).join('')}</div>`;
  if(tab==='social')return `<div class="grid two">${data.social.length?data.social.map(x=>`<article class="social-card"><div class="social-platform">${esc(x.platform)}</div><h3>${esc(x.title||'Social content')}</h3><p>${esc(x.post_text)}</p><div class="hashtags">${esc(x.hashtags)}</div><div class="card-actions"><button class="button secondary small" data-copy-text="${x.id}">Copy Post</button><button class="button secondary small" data-copy-tags="${x.id}">Copy Hashtags</button>${!readOnly&&x.status!=='PUBLISHED_MANUALLY'?`<button class="button small" data-publish-social="${x.id}">Mark Published</button>`:''}${badge(title(x.status),statusTone(x.status))}</div></article>`).join(''):empty('No social content','Generate platform-specific posts for Facebook, Instagram, LinkedIn and X.')}</div>`;
  if(tab==='email')return `<section class="table-card"><table class="data-table"><thead><tr><th>Recipient</th><th>Subject</th><th>Status</th><th>CRM / PIQ</th><th>Sent</th></tr></thead><tbody>${data.messages.length?data.messages.map(x=>`<tr><td>${esc(x.recipient_email)}</td><td><strong>${esc(x.subject)}</strong></td><td>${badge(title(x.status),statusTone(x.status))}</td><td>${x.crm_record_id?'CRM':''}${x.crm_record_id&&x.piq_record_id?' · ':''}${x.piq_record_id?'PIQ':''}</td><td>${fmtDateTime(x.sent_at||x.created_at)}</td></tr>`).join(''):'<tr><td colspan="5">No outreach messages yet.</td></tr>'}</tbody></table></section>`;
  const items=[...data.campaigns.map(x=>({date:x.scheduled_at||x.created_at,title:x.title,type:x.channel,status:x.status})),...data.social.map(x=>({date:x.published_at||x.created_at,title:x.title||x.platform,type:x.platform,status:x.status}))].sort((a,b)=>new Date(a.date)-new Date(b.date));return `<div class="calendar-list">${items.map(x=>`<div class="calendar-row"><time>${dateFmt(x.date)}</time><span class="badge gray">${esc(x.type)}</span><strong class="grow">${esc(x.title)}</strong>${badge(title(x.status),statusTone(x.status))}</div>`).join('')}</div>`;
}
function campaignModal(ctx){modal({title:'New campaign',body:`<form class="form-grid">${field('Campaign title','title','text','',true)}${select('Channel','channel',[['Email','Email'],['Facebook','Facebook'],['Instagram','Instagram'],['LinkedIn','LinkedIn'],['Multi-channel','Multi-channel']])}${select('Status','status',[['Draft','Draft'],['Approved','Approved'],['Scheduled','Scheduled']])}${textarea('Campaign message','content','')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-campaign">Create Campaign</button>',onOpen:(root,close)=>$('#save-campaign',root).addEventListener('click',async()=>{const f=$('form',root);try{await api(`/api/tenants/${state.selectedTenantId}/campaigns`,{method:'POST',body:{title:f.title.value,channel:f.channel.value,status:f.status.value,content:f.content.value}});toast('Campaign created');close();ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}})});}
function socialModal(ctx){modal({title:'Generate social content',wide:true,body:`<form class="form-grid">${field('Content title','title','text','',true)}${textarea('Core message','message','', 'Write the human-reviewed message that should be adapted for each platform.')}${field('Call to action','call_to_action','text','Learn more')}${field('Hashtags (comma separated)','hashtags','text','')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-social">Generate Four Posts</button>',onOpen:(root,close)=>$('#save-social',root).addEventListener('click',async()=>{const f=$('form',root);try{await api(`/api/tenants/${state.selectedTenantId}/marketing/generate-social`,{method:'POST',body:{title:f.title.value,message:f.message.value,call_to_action:f.call_to_action.value,hashtags:f.hashtags.value.split(',').map(x=>x.trim()).filter(Boolean)}});toast('Facebook, Instagram, LinkedIn and X drafts created');close();ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}})});}
function publishSocialModal(id,ctx){modal({title:'Record manual publication',body:`${field('Published post URL','url','url','',true)}`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="save-published">Mark Published</button>',onOpen:(root,close)=>$('#save-published',root).addEventListener('click',async()=>{try{await api(`/api/social-content/${id}/published`,{method:'POST',body:{published_url:$('[name=url]',root).value}});toast('Publication recorded');close();ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}})});}
function generateOutreachModal(ctx){modal({title:'Generate supported outreach',wide:true,body:`<form class="form-grid">${field('Recipient name','recipient_name','text','')}${field('Recipient email','recipient_email','email','',true)}${textarea('Supported facts (one per line)','facts','')}${textarea('Call to action','call_to_action','Would a brief conversation be worthwhile?')}</form><div id="generated-email"></div>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button secondary" id="generate-email-draft">Generate Draft</button><button class="button" id="send-generated-email" disabled>Send & Record</button>',onOpen:(root,close)=>{let draft=null;$('#generate-email-draft',root).addEventListener('click',async()=>{const f=$('form',root);try{const d=await api(`/api/tenants/${state.selectedTenantId}/marketing/generate-email`,{method:'POST',body:{recipient_name:f.recipient_name.value,recipient_email:f.recipient_email.value,facts:parseLines(f.facts.value),call_to_action:f.call_to_action.value}});draft=d.draft;$('#generated-email',root).innerHTML=`<div class="notice-card"><strong>Subject</strong><input id="generated-subject" value="${esc(draft.subject)}"><strong>Body</strong><textarea id="generated-body" style="min-height:180px">${esc(draft.body)}</textarea></div>`;$('#send-generated-email',root).disabled=false}catch(e){toast(e.message,'error')}});$('#send-generated-email',root).addEventListener('click',async()=>{const f=$('form',root);try{await api(`/api/tenants/${state.selectedTenantId}/crm/email`,{method:'POST',body:{recipient_email:f.recipient_email.value,recipient_name:f.recipient_name.value,subject:$('#generated-subject',root).value,body:$('#generated-body',root).value,supported_facts:parseLines(f.facts.value),send_now:true}});toast('Email sent in demo provider mode and recorded in CRM activity');close();ctx.navigate('campaigns')}catch(e){toast(e.message,'error')}})}});}

async function emailActivities(page,ctx,readOnly){const [status,timeline,marketing]=await Promise.all([api(`/api/tenants/${state.selectedTenantId}/email-status`),api(`/api/tenants/${state.selectedTenantId}/timeline?limit=150`),api(`/api/tenants/${state.selectedTenantId}/marketing`).catch(()=>({messages:[]}))]);page.innerHTML=`${pageHead('Email & Activities','Send from the connected client identity, record communication in CRM and review one cross-module activity history.',!readOnly?'<button class="button" id="new-email">+ New Email</button>':'')}${readOnly?readonlyBanner():''}<div class="kpi-grid">${kpi('Email mode',title(status.provider_mode),'Client sender configuration')}${kpi('Connections',number(status.connections.length),'Business mailbox adapters')}${kpi('Recorded messages',number(marketing.messages.length),'Outreach activity')}${kpi('Timeline events',number(timeline.events.length),'Cross-module history')}</div><div class="grid two"><section class="card"><h2>Connected senders</h2>${status.connections.length?status.connections.map(x=>`<div class="list-item"><span class="grow"><strong>${esc(x.sender_name||x.sender_email)}</strong><small>${esc(x.provider)} · ${esc(x.sender_email)} · ${esc(x.physical_address)}</small></span>${badge(title(x.status),statusTone(x.status))}</div>`).join(''):`<div class="notice-card"><strong>Safe demo provider</strong><p>Email is recorded without external delivery until a client mailbox is connected.</p></div>`}</section><section class="card"><h2>Unified activity timeline</h2><div class="timeline-list">${timeline.events.map(timelineRow).join('')}</div></section></div>`;$('#new-email')?.addEventListener('click',()=>emailModal({},ctx));}
function emailModal(seed,ctx){modal({title:'Send email and record CRM activity',wide:true,body:`<form class="form-grid">${field('Recipient name','recipient_name','text',seed.recipient_name||'')}${field('Recipient email','recipient_email','email',seed.recipient_email||'',true)}${field('Subject','subject','text','',true)}${textarea('Message','body','')}${textarea('Supported facts (one per line)','supported_facts','')}</form>`,footer:'<button class="button secondary" data-close-modal>Cancel</button><button class="button" id="send-crm-email">Send & Record</button>',onOpen:(root,close)=>$('#send-crm-email',root).addEventListener('click',async()=>{const f=$('form',root);try{await api(`/api/tenants/${state.selectedTenantId}/crm/email`,{method:'POST',body:{recipient_email:f.recipient_email.value,recipient_name:f.recipient_name.value,subject:f.subject.value,body:f.body.value,opportunity_id:seed.opportunity_id||null,account_id:seed.account_id||null,piq_record_id:seed.piq_record_id||null,supported_facts:parseLines(f.supported_facts.value),send_now:true}});toast('Email sent in configured provider mode and recorded as CRM activity');close();ctx.navigate('email')}catch(e){toast(e.message,'error')}})});}

async function reports(page,ctx,readOnly){const [growth,ttm]=await Promise.all([api(`/api/tenants/${state.selectedTenantId}/growth-report`),api(`/api/tenants/${state.selectedTenantId}/reports/ttm`).catch(()=>({summary:{},accounts:[]}))]);const s=growth.summary;page.innerHTML=`${pageHead('Growth & Management Reporting','Connect website, ProspectIQ, CRM, campaigns, email, pipeline and revenue evidence in one view.')}<div class="kpi-grid">${kpi('Website leads',number(growth.funnel.website_leads),'Lead capture')}${kpi('PIQ prospects',number(growth.funnel.piq_records),'Scored records')}${kpi('PIQ to CRM',number(growth.funnel.piq_to_crm),'Qualified handoff')}${kpi('Open opportunities',number(growth.funnel.open_opportunities),'Pipeline')}${kpi('Won opportunities',number(growth.funnel.won_opportunities),'Conversions')}${kpi('Won revenue',money(growth.won_revenue_cents),'Attributed value')}${kpi('Social drafts',number(growth.funnel.social_drafts),'Content activity')}${kpi('Emails',number(growth.funnel.emails),'Recorded outreach')}</div><div class="grid two"><section class="card"><h2>Growth funnel</h2>${funnelBars(growth.funnel)}</section><section class="card"><h2>Source attribution</h2>${growth.attribution.length?growth.attribution.map(x=>`<div class="attribution-row"><strong>${esc(x.source)}</strong><span>${number(x.opportunities)} opportunities</span><b>${money(x.won_revenue_cents)}</b></div>`).join(''):empty('No attribution yet','Opportunity sources will appear after CRM activity.')}</section></div><section class="table-card"><div class="table-toolbar"><h2>Trailing Twelve Months by account</h2></div><div class="table-wrap no-vertical"><table class="data-table"><thead><tr><th>Account</th><th>Team</th><th>Prior TTM</th><th>Current TTM</th><th>Change</th><th>Forecast</th></tr></thead><tbody>${(ttm.accounts||[]).map(x=>`<tr><td><strong>${esc(x.account_name)}</strong></td><td>${esc(x.team_name)}</td><td>${money(x.prior_ttm_cents)}</td><td>${money(x.current_ttm_cents)}</td><td class="${x.change_cents>=0?'positive':'negative'}">${money(x.change_cents)}</td><td>${money(x.forecast_cents)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function funnelBars(f){const rows=[['Website leads',f.website_leads],['PIQ records',f.piq_records],['PIQ moved to CRM',f.piq_to_crm],['Open opportunities',f.open_opportunities],['Won opportunities',f.won_opportunities]];const max=Math.max(...rows.map(x=>x[1]),1);return `<div class="chart-bars">${rows.map(([l,v])=>`<div class="bar-row"><span>${l}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(3,v/max*100)}%"></div></div><strong>${number(v)}</strong></div>`).join('')}</div>`;}

async function remove(path,message,ctx,route){if(!confirm('Delete this item?'))return;try{await api(path,{method:'DELETE',body:{}});toast(message);ctx.navigate(route)}catch(e){toast(e.message,'error')}}
